@ObjectType({ description: `The tunable inputs a forecast run was computed under, versioned. A snapshot points at the set it used, so changing an assumption becomes an AssumptionChange in the next bridge rather than silent drift.` })
export class mjBizAppsFPNAAssumptionSet_ {
    @Field() 
    @MaxLength(36)
    ID: string;
        
    @Field() 
    @MaxLength(36)
    PlanID: string;
        
    @Field({description: `Human label for this version of the assumptions.`}) 
    @MaxLength(200)
    Name: string;
        
    @Field({description: `First instant this set applies from. UTC.`}) 
    EffectiveFrom: Date;
        
    @Field({description: `Draft, Active or Retired. Only an Active set should back a published run.`}) 
    @MaxLength(20)
    Status: string;
        
    @Field(() => Float, {description: `Minimum line Weight for a pipeline deal to contribute cash. Deals below it contribute zero rather than a fraction, because payroll cannot be met with fractional promises.`}) 
    PipelineCashMinWeight: number;
        
    @Field(() => Int, {description: `Length of the near-term ramp over which unbacked new-business budget decays to zero. A ramp, not a step, so there is no cliff at the boundary.`}) 
    NearTermDecayDays: number;
        
    @Field(() => Int, {description: `Default days from due date to observed cash, used where no per-customer override exists.`}) 
    CollectionLagDaysDefault: number;
        
    @Field(() => Float, {description: `Reserve rate applied to Assumed-confidence renewal lines. Applied as a visible reserve line, never as a haircut baked into the renewal itself.`}) 
    RenewalChurnRate: number;
        
    @Field(() => Int, {description: `Week convention, 0=Sunday..6=Saturday, default 5 (Friday). A view concern; changing it never rewrites stored lines.`}) 
    WeekEndingDay: number;
        
    @Field(() => Int, {description: `Default forward window the distribution policy evaluates its trough over, where a company has no per-entity override.`}) 
    DistributionLookaheadDaysDefault: number;
        
    @Field({nullable: true, description: `Why these values, and who set them.`}) 
    Notes?: string;
        
    @Field() 
    _mj__CreatedAt: Date;
        
    @Field() 
    _mj__UpdatedAt: Date;
        
    @Field(() => Float, {description: `Deal Probability used when the sales row has none. 0–1. Not inferred from other deals.`}) 
    DefaultProbability: number;
        
    @Field(() => Float, {description: `Minimum Weight for an IncludeInCommit deal. The category floor, not a full-amount override. 0–1.`}) 
    CommitCashMinWeight: number;
        
    @Field() 
    @MaxLength(200)
    Plan: string;
        
}

