//****************************************************************************
// ENTITY CLASS for MJ_BizApps_FPNA: Distribution Policies
//****************************************************************************
@ObjectType({ description: `Per-company rule for whether a distribution is permitted and how much. Effective-dated: a snapshot names the exact version it was computed under, so a bridge can attribute a change in headroom to a change in the floor.` })
export class mjBizAppsFPNADistributionPolicy_ {
    @Field() 
    @MaxLength(36)
    ID: string;
        
    @Field() 
    @MaxLength(36)
    CompanyID: string;
        
    @Field({description: `FixedAmount or MonthsOfOpex — how the cash floor is expressed.`}) 
    @MaxLength(20)
    FloorType: string;
        
    @Field(() => Float, {nullable: true, description: `Floor in currency, when FloorType is FixedAmount.`}) 
    FloorAmount?: number;
        
    @Field(() => Float, {nullable: true, description: `Floor as N months of trailing operating expense, when FloorType is MonthsOfOpex.`}) 
    FloorMonths?: number;
        
    @Field(() => Int, {description: `Forward window whose minimum projected cash is tested against the floor. 90 or 180, per entity.`}) 
    LookaheadDays: number;
        
    @Field(() => Int, {description: `Month the distribution year begins. Ours is February.`}) 
    DistributionYearStartMonth: number;
        
    @Field(() => Int, {description: `Day of that month the distribution year begins. Ours is the 15th, so the year runs 2/15 to 1/15. Month alone cannot express it, and a calendar-year assumption resets the preference tier two weeks early for every entity.`}) 
    DistributionYearStartDay: number;
        
    @Field({description: `First instant this version of the policy applies from.`}) 
    EffectiveFrom: Date;
        
    @Field({description: `Draft, Active or Retired. Status is the authority — there is no parallel IsActive flag.`}) 
    @MaxLength(20)
    Status: string;
        
    @Field() 
    _mj__CreatedAt: Date;
        
    @Field() 
    _mj__UpdatedAt: Date;
        
    @Field(() => Float, {nullable: true, description: `Monthly operating-expense run-rate for FloorType=MonthsOfOpex. Floor = this × FloorMonths. Required when FloorType is MonthsOfOpex — not inferred from whatever Opex lines happen to be in the run.`}) 
    MonthlyOpexBaseline?: number;
        
    @Field(() => Int, {description: `Maximum age in days of the CashBalance used as OpeningCash relative to AsOf. Older balances fail STALE_OPENING_CASH rather than silently driving the trough.`}) 
    OpeningCashMaxAgeDays: number;
        
    @Field() 
    @MaxLength(50)
    Company: string;
        
}

