//****************************************************************************
// ENTITY CLASS for MJ_BizApps_FPNA: Forecast Lines
//****************************************************************************
@ObjectType({ description: `One forecast line: this invoice, this renewal, this deal, this expense. The primary artifact — every weekly and monthly position is derived from these rows, never stored as truth of its own. INVARIANTS NOT ENFORCED BY THE DATABASE: a line\'s Plan is its run\'s (ForecastLine carries no PlanID — read ForecastRun.PlanID), and every line of a company shares that company\'s functional currency. Both are asserted by the materializer and covered by integration checks. A composite FOREIGN KEY could enforce the first, but MJ models a foreign key as a single RelatedEntityFieldName, so a two-column key is invisible to CodeGen and to the generated entity — and its target requires a UNIQUE (ID, col) that reads as a mistake next to the primary key. No other schema in the bizapps family or MJ core uses one. CURRENCY IS SINGLE-VALUED FOR NOW: there is no per-line conversion pair, because FX is deferred upstream — accounting D16 defers all FX computation to Orders/Payments, and orders MOD-4 defers its currency columns, so nothing upstream can supply a rate. A mixed-currency line set fails loudly instead of summing wrong.` })
export class mjBizAppsFPNAForecastLine_ {
    @Field() 
    @MaxLength(36)
    ID: string;
        
    @Field() 
    @MaxLength(36)
    RunID: string;
        
    @Field() 
    @MaxLength(36)
    CompanyID: string;
        
    @Field() 
    @MaxLength(36)
    StreamID: string;
        
    @Field() 
    @MaxLength(36)
    ForecastCategoryID: string;
        
    @Field({nullable: true}) 
    @MaxLength(36)
    StatementLineID?: string;
        
    @Field({nullable: true}) 
    @MaxLength(36)
    GLAccountID?: string;
        
    @Field({description: `Stable identity across runs and snapshots. The bridge matches on this, never on the row's UUID, which is regenerated every run.`}) 
    @MaxLength(200)
    LineKey: string;
        
    @Field({description: `When the cash moves. Stored to the day; week and month buckets are derived at read time in the company's operating time zone and never persisted.`}) 
    ExpectedAt: Date;
        
    @Field(() => Float, {description: `Cash contribution, signed. For a budget residual this is gross less what has been displaced.`}) 
    Amount: number;
        
    @Field(() => Float, {description: `Amount before displacement. Equals Amount for any line that is not a budget residual.`}) 
    GrossAmount: number;
        
    @Field(() => Float, {description: `Magnitude displaced by higher-fidelity lines. Never exceeds the magnitude of GrossAmount, so a residual reaches zero and never inverts.`}) 
    DisplacedAmount: number;
        
    @Field({description: `Currency this line is denominated in — the company's functional currency. FK to __mj_BizAppsAccounting.Currency, resolved from AccountingCompanyProfile.FunctionalCurrencyCode. Single-currency until multi-currency activates upstream (accounting D16 / orders MOD-4).`}) 
    @MaxLength(36)
    CurrencyID: string;
        
    @Field(() => Float, {description: `Source confidence, 0 to 1. A 35% pipeline deal keeps its 0.35 here; cash inclusion is a separate test against the assumption set's threshold.`}) 
    Weight: number;
        
    @Field({nullable: true, description: `Entity of the source record in __mj.Entity. NULL until the source app is wired.`}) 
    @MaxLength(36)
    OriginEntityID?: string;
        
    @Field({nullable: true, description: `Primary key of the source record, as text.`}) 
    @MaxLength(400)
    OriginRecordID?: string;
        
    @Field({nullable: true, description: `Human-readable source reference, e.g. 'Acme INV-1042'.`}) 
    @MaxLength(200)
    OriginLabel?: string;
        
    @Field({nullable: true, description: `The line this one derives from — a commission points at the receipt it is calculated on.`}) 
    @MaxLength(36)
    ParentForecastLineID?: string;
        
    @Field({nullable: true, description: `The manual override that produced this line, when it came from one rather than from a source system.`}) 
    @MaxLength(36)
    AdjustmentID?: string;
        
    @Field({nullable: true, description: `Contracted (a signed term exists, amount used as-is) or Assumed (annualised, escalator applied). Provenance, deliberately distinct from likelihood: judgment is applied once as a visible reserve, never as a haircut on the line.`}) 
    @MaxLength(20)
    ConfidenceClass?: string;
        
    @Field({nullable: true, description: `Shared key linking the due-to line at one company to the due-from line at the other, so a pair can be asserted to net to zero on consolidation instead of inferred from sums.`}) 
    @MaxLength(200)
    IntercompanyPairKey?: string;
        
    @Field({description: `What the bridge shows for this line.`}) 
    @MaxLength(200)
    Name: string;
        
    @Field() 
    _mj__CreatedAt: Date;
        
    @Field() 
    _mj__UpdatedAt: Date;
        
    @Field() 
    @MaxLength(50)
    Company: string;
        
    @Field() 
    @MaxLength(200)
    Stream: string;
        
    @Field() 
    @MaxLength(200)
    ForecastCategory: string;
        
    @Field({nullable: true}) 
    @MaxLength(200)
    StatementLine?: string;
        
    @Field({nullable: true}) 
    @MaxLength(200)
    GLAccount?: string;
        
    @Field() 
    @MaxLength(80)
    Currency: string;
        
    @Field({nullable: true}) 
    @MaxLength(255)
    OriginEntity?: string;
        
    @Field({nullable: true}) 
    @MaxLength(200)
    ParentForecastLine?: string;
        
}

