//****************************************************************************
// ENTITY CLASS for MJ_BizApps_FPNA: Simulation Periods
//****************************************************************************
@ObjectType({ description: `Per-company audit of the forward cash chain, one row per simulated period. Not a second source of truth — the lines remain primary; this makes the chain assertable without re-deriving the whole horizon.` })
export class mjBizAppsFPNASimulationPeriod_ {
    @Field() 
    @MaxLength(36)
    ID: string;
        
    @Field() 
    @MaxLength(36)
    ForecastRunID: string;
        
    @Field() 
    @MaxLength(36)
    CompanyID: string;
        
    @Field({description: `First instant of the simulated period.`}) 
    PeriodStart: Date;
        
    @Field({description: `Last instant of it.`}) 
    PeriodEnd: Date;
        
    @Field(() => Int, {description: `Position in the run, 0-based. Closing cash of N is opening cash of N+1.`}) 
    Sequence: number;
        
    @Field(() => Float, {description: `Cash at the start of the period.`}) 
    OpeningCash: number;
        
    @Field(() => Float, {description: `Net operating movement in the period. EXCLUDES distribution streams, which are counted once in the two distribution columns.`}) 
    OperatingCash: number;
        
    @Field(() => Float, {description: `Lowest projected cash inside the policy look-ahead window. What the floor is tested against.`}) 
    MinLookaheadCash: number;
        
    @Field(() => Float, {description: `Cash floor in force for this company and period.`}) 
    FloorAmount: number;
        
    @Field(() => Float, {description: `Headroom: look-ahead trough less floor, never below zero.`}) 
    Distributable: number;
        
    @Field(() => Float, {description: `Distributions paid out this period, as a positive magnitude.`}) 
    DistributedOut: number;
        
    @Field(() => Float, {description: `Distributions received this period, as a positive magnitude. Kept separate from outbound because at HQ one signed column would mix the two and the cash chain could not be checked.`}) 
    DistributedIn: number;
        
    @Field(() => Float, {description: `Cash at the end of the period.`}) 
    ClosingCash: number;
        
    @Field({description: `Currency all amounts in this row are stated in.`}) 
    @MaxLength(36)
    CurrencyID: string;
        
    @Field() 
    _mj__CreatedAt: Date;
        
    @Field() 
    _mj__UpdatedAt: Date;
        
    @Field() 
    @MaxLength(50)
    Company: string;
        
    @Field() 
    @MaxLength(80)
    Currency: string;
        
}

