@ObjectType({ description: `Per-company distribution state frozen with the photo: how much has been distributed so far in the distribution year, and the exact terms it was computed under. There is deliberately no separate mutating seed table — a running total the simulation edits would be a second source of truth.` })
export class mjBizAppsFPNASnapshotState_ {
    @Field() 
    @MaxLength(36)
    ID: string;
        
    @Field() 
    @MaxLength(36)
    SnapshotID: string;
        
    @Field(() => Int, {description: `The distribution year this state belongs to, identified by the year its start date falls in.`}) 
    DistributionYear: number;
        
    @Field(() => Float, {description: `Cumulative distributed within that year as of this photo. What decides whether a preference band is still open.`}) 
    YTDDistributed: number;
        
    @Field({description: `Currency of YTDDistributed.`}) 
    @MaxLength(36)
    CurrencyID: string;
        
    @Field({nullable: true, description: `The exact policy version this state was computed under.`}) 
    @MaxLength(36)
    DistributionPolicyID?: string;
        
    @Field({nullable: true, description: `The exact waterfall version this state was computed under.`}) 
    @MaxLength(36)
    WaterfallSpecID?: string;
        
    @Field(() => Boolean, {description: `True for the opening balance of a distribution year that began before go-live. Without a seed the first run reads cumulative as zero and over-allocates the preference tier before it should flip.`}) 
    IsSeed: boolean;
        
    @Field({nullable: true, description: `Where the opening figure came from, e.g. the month-end partner distributions tracker. Required on a seed: this number decides who gets paid.`}) 
    @MaxLength(200)
    SeedSource?: string;
        
    @Field({nullable: true, description: `The date the seed figure was true as of.`}) 
    SeedAsOf?: Date;
        
    @Field({nullable: true, description: `Who entered the seed.`}) 
    @MaxLength(36)
    SeedEnteredByUserID?: string;
        
    @Field({nullable: true, description: `When the seed was verified against the system's own recorded distribution history. After this point the computed history is authoritative and the seed is no longer relied on.`}) 
    SeedReconciledAt?: Date;
        
    @Field() 
    _mj__CreatedAt: Date;
        
    @Field() 
    _mj__UpdatedAt: Date;
        
    @Field() 
    @MaxLength(80)
    Currency: string;
        
    @Field({nullable: true}) 
    @MaxLength(100)
    SeedEnteredByUser?: string;
        
}

